return items.map(item => {
  const body = item.json.body ?? {};
  return {
    json: {
      ...item.json,
      body: {
        ...body,
        data_formatada: body.data_formatada || body.data || "",
        hora_inicio: body.hora_inicio || body.hora || "",
        hora_fim: body.hora_fim || "",
        horario_evento: body.horario_evento || ""
      }
    }
  };
});

